CREATE OR REPLACE FUNCTION private.izytel_calculate_order_economics(p_network text, p_order_amount bigint, p_acquisition_source text, p_executor_type text, p_executor_id text, p_referring_cabiniste_id text DEFAULT NULL::text, p_manager_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_network text := lower(btrim(coalesce(p_network, '')));
  v_acquisition_source text := lower(btrim(coalesce(p_acquisition_source, '')));
  v_executor_type text := lower(btrim(coalesce(p_executor_type, '')));
  v_executor_id text := nullif(btrim(coalesce(p_executor_id, '')), '');
  v_manager_id text := nullif(btrim(coalesce(p_manager_id, '')), '');
  v_plan public.compensation_plans%rowtype;
  v_plan_scope text;
  v_margin_bps integer;
  v_partner_share_bps integer := 0;
  v_izytel_share_bps integer := 10000;
  v_margin_amount bigint;
  v_partner_margin_amount bigint := 0;
  v_izytel_margin_amount bigint;
  v_settlement_amount bigint := 0;
  v_customer_fee bigint := 10;
  v_gross_gain bigint;
begin
  if p_order_amount is null or p_order_amount <= 0 then
    raise exception 'INVALID_ORDER_AMOUNT';
  end if;

  if v_network not in ('orange', 'mtn', 'moov') then
    raise exception 'INVALID_NETWORK';
  end if;

  if v_acquisition_source <> 'izytel' then
    raise exception 'UNSUPPORTED_ACQUISITION_SOURCE';
  end if;

  if v_executor_type not in ('agent', 'cabiniste') then
    raise exception 'INVALID_EXECUTOR_TYPE';
  end if;

  if v_executor_id is null then
    raise exception 'EXECUTOR_REQUIRED';
  end if;

  v_margin_bps := case
    when v_network in ('orange', 'mtn') then 400
    when v_network = 'moov' then 450
  end;

  v_plan_scope := case
    when v_executor_type = 'agent' then 'direct'
    else 'standard'
  end;

  select p.*
    into v_plan
  from public.compensation_plans p
  where p.actor_type = case
      when v_executor_type = 'agent' then 'agent'
      else 'cabiniste'
    end
    and p.plan_scope = v_plan_scope
    and p.status in ('active', 'draft')
    and (p.effective_from is null or p.effective_from <= now())
    and (p.effective_to is null or p.effective_to > now())
  order by
    case when p.status = 'active' then 0 else 1 end,
    p.version desc
  limit 1;

  if not found then
    raise exception 'ECONOMIC_PLAN_NOT_FOUND';
  end if;

  if v_executor_type = 'cabiniste' then
    v_partner_share_bps := coalesce(v_plan.partner_margin_share_bps, 0);
    v_izytel_share_bps := coalesce(
      v_plan.izytel_margin_share_bps,
      10000 - v_partner_share_bps
    );

    if v_partner_share_bps + v_izytel_share_bps <> 10000 then
      raise exception 'INVALID_MARGIN_SHARE_PLAN';
    end if;
  end if;

  v_margin_amount := round(
    (p_order_amount::numeric * v_margin_bps::numeric) / 10000
  )::bigint;

  v_partner_margin_amount := round(
    (v_margin_amount::numeric * v_partner_share_bps::numeric) / 10000
  )::bigint;

  v_izytel_margin_amount := v_margin_amount - v_partner_margin_amount;

  if v_executor_type = 'cabiniste' then
    v_settlement_amount := p_order_amount - v_izytel_margin_amount;
  end if;

  v_gross_gain := v_izytel_margin_amount + v_customer_fee;

  return jsonb_build_object(
    'network', v_network,
    'order_amount', p_order_amount,
    'acquisition_source', 'izytel',
    'executor_type', v_executor_type,
    'executor_id', v_executor_id,
    'referring_cabiniste_id', null,
    'manager_id', v_manager_id,
    'economic_policy_id', v_plan.plan_code,
    'telecom_margin_bps', v_margin_bps,
    'telecom_margin_amount', v_margin_amount,
    'customer_fee_amount', v_customer_fee,
    'cabiniste_margin_share_bps', v_partner_share_bps,
    'cabiniste_margin_amount', v_partner_margin_amount,
    'izytel_margin_amount', v_izytel_margin_amount,
    'cabiniste_settlement_amount', v_settlement_amount,
    'izytel_gross_gain', v_gross_gain
  );
end;
$function$
